const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const SWORD_BASE_PREMIUM = 100;

/** Percentages are applied as integer arithmetic so that the final
 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

/** Rounds up — premiums round in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const itemBasePremium = (_item: Item): number => SWORD_BASE_PREMIUM;

const policyBasePremium = (items: Item[]): number =>
  items.reduce((total, item) => total + itemBasePremium(item), 0);

const quote = (step: QuoteStep): StepResult => {
  const basePremium = policyBasePremium(step.items);
  const premium =
    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map((step) => quote(step as QuoteStep));
  return { results };
};

